-- Roadmap status after the Nov 9 stack-standard pass (data only).
update roadmap_items set lane='done', done_at=now(), updated_at=now(), detail='Done Nov 9: 18 or older. Stated in the terms (Who can use it) and privacy policy (Children), and confirmed with a checkbox on sign-up (Apple and Google sign-up confirm it in the fine print). Use 18+ in both store age ratings. A lawyer should still read it as part of Legal review.' where title='Minimum age';
update roadmap_items set updated_at=now(), detail='Who: Austin. Still blocked: Stripe keys are not in Vercel, so the live site reports payments off. Add STRIPE_SECRET_KEY (test mode) and STRIPE_WEBHOOK_SECRET to both Vercel projects (app and takeitback-site), then Claude buys each plan with a test card and checks the plan turns on, the receipt arrives and cancel works.' where title='Test purchase on the website';
update roadmap_items set updated_at=now(), detail='Who: Claude builds, a lawyer confirms. Checked Nov 9 (docs/texas-age-law.md): in force since Jun 4, 2026. For new Texas accounts the app must read the store''s age range (Apple Declared Age Range, Google Play age signals) and apply age limits; minors need parental consent through the store, again after significant changes. With the 18+ terms and an 18+ rating, minors should be blocked by the store, but the age-range check is still needed in the phone apps. Ask the lawyer whether it must ship before the first Texas download.' where title='Texas app store age law';
update roadmap_items set lane='done', done_at=now(), updated_at=now(), detail='Done Nov 9: the Android release bundle is checked on every build; all 4 native libraries are 16 KB aligned.' where title='16 KB check on the release build';
update roadmap_items set updated_at=now(), detail='Who: Claude. Nov 9: the upload key fingerprint is live in assetlinks.json (ANDROID_CERT_SHA256 in Vercel). After the first Play upload, add the Google Play app-signing fingerprint to the same setting, comma-separated.' where title='Android app links';
update roadmap_items set updated_at=now(), detail='Who: Austin on the Apple account; the build itself runs in GitHub. Both iPhone workflows now require Xcode 26 (the simulator check passed on Xcode 26.6 on Nov 9). Left: the Apple account, signing, and push set to production when archiving.' where title='iPhone build in Xcode 26';
update roadmap_items set updated_at=now(), detail='Who: Austin. Create a token at supabase.com/dashboard/account/tokens and add it as the GitHub secret SUPABASE_ACCESS_TOKEN in Take-it-Back/takeitback-app. That switches on the types drift check and the row-level security tests in CI (they pass but skip until then), and lets Claude turn on leaked-password protection and Resend sign-up emails.' where title='Supabase access token for Claude';
update roadmap_items set updated_at=now(), detail='Who: Claude. Nov 9: generated types, migrations from today on, and RLS tests are in the repo. Left: the full older schema as migration files, which needs the Supabase access token.' where title='Database setup in the code';
update roadmap_items set updated_at=now(), detail='Who: Claude, with approval to deploy. The function code now checks CRON_SECRET and reads the new secret key (Nov 9, not deployed). Left: set CRON_SECRET as a function secret, deploy, and change the cron job to send it instead of the old anon key. Must happen before the old Supabase keys are switched off.' where title='Lock the reminder job';

insert into roadmap_items (title, detail, lane, priority, area, sort, done_at) values
('Fix keys on the site project', 'Who: Austin. Since Nov 7 www.takeitback.app runs on the new takeitback-site Vercel project, which is missing BILLING_SECRET, RESEND_API_KEY, VAPID_PRIVATE_KEY, FIREBASE_SERVICE_ACCOUNT and GOOGLE_PLAY_SERVICE_ACCOUNT. On www, support emails, billing checks, Google Play notifications and push fail, the phone apps load www, and /status shows App and database down. Copy those from the app project, then redeploy takeitback-site. Non-secret settings were copied Nov 9.', 'now', 'high', '1 · Switch on the website', 100, null),
('New Supabase keys', 'Who: Austin, then Claude checks. Steps in docs/supabase-keys.md: add NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY (same sb_publishable value) and SUPABASE_SECRET_KEY to both Vercel projects, redeploy, check /api/health shows new_publishable_key and secret_key true, then remove the old names. Disable the legacy keys in Supabase only after the reminder job is moved off the old anon key.', 'now', 'high', '1 · Switch on the website', 99, null),
('Close billing functions to the public API', 'Who: Claude, after SUPABASE_SECRET_KEY is live. The server already calls billing, send and support functions with the secret key when it is set. Then apply supabase/pending/close_secret_functions_to_api.sql so only the server can call them (they still check BILLING_SECRET).', 'next', 'normal', '6 · Safety nets', 610, null),
('Move pg_net out of public', 'Who: Claude, with approval. Drop and re-create the pg_net extension in the extensions schema. Uptime checks pause for about a minute; nothing else uses it.', 'next', 'low', '6 · Safety nets', 611, null),
('Texas age check in the phone apps', 'Who: Claude. Read the store age range for new Texas users (Apple Declared Age Range on iOS 26, Google Play age signals) and block under 18. Needs a native plugin or the Phase 3 phone app.', 'next', 'normal', '3 · Apple app', 307, null),
('Phone builds ready for the monorepo', 'Done Nov 9: the iPhone and Android workflows run from any folder (repo variable MOBILE_APP_DIR). A test moved the app into apps/web inside GitHub and both apps built and launched there. At cutover set MOBILE_APP_DIR to apps/web.', 'done', 'high', '6 · Safety nets', 693, now()),
('Database function access review', 'Done Nov 9 (docs/security-review-2026-11-09.md): trigger functions and an unused helper closed to the API, new functions closed to signed-out callers by default, the 16 remaining signed-out functions each check a secret, a guest token, or are public on purpose. The 6 tables without policies are server-only.', 'done', 'high', '6 · Safety nets', 694, now()),
('Sentry test error', 'Done Nov 9: test errors sent from the browser on app.takeitback.app and www (Sentry accepted them) and from the server on both (500 thrown, reported by the Sentry hook). Confirm the server events in Sentry once signed in. The test page and route close on their own; delete SENTRY_TEST_UNTIL in Vercel when done.', 'done', 'normal', '6 · Safety nets', 695, now()),
('Forced-update gate', 'Done Nov 9: the phone apps check app_settings in Supabase at launch (min_supported_version_ios and _android, now 0.0.0) and show an update screen if they are older. Change the row, no deploy needed. Version logic has unit tests.', 'done', 'normal', '6 · Safety nets', 696, now()),
('Types drift check and RLS tests in CI', 'Done Nov 9: lib/database.types.ts generated from the database; CI regenerates and compares it, and runs tests/rls/rls.sql (two users and a signed-out visitor, function access, always rolled back). Both skip until the SUPABASE_ACCESS_TOKEN secret is added.', 'done', 'normal', '6 · Safety nets', 697, now());
